from __future__ import annotations

from relocation_jobs.scrape.relevance import is_relevant


def filter_relevant_jobs(
    jobs: list[dict],
    relevant_only: bool,
    *,
    include: list[str] | None = None,
    exclude: list[str] | None = None,
) -> list[dict]:
    out: list[dict] = []
    for job in jobs:
        title = (job.get("title") or "").strip()
        url = (job.get("url") or "").strip()
        if not title or not url:
            continue
        if relevant_only:
            if include is None or exclude is None:
                raise TypeError("include and exclude required when relevant_only")
            if not is_relevant(title, include=include, exclude=exclude):
                continue
        entry = {"title": title, "url": url}
        location = (job.get("location") or "").strip()
        if location:
            entry["location"] = location
        if job.get("locations") is not None:
            entry["locations"] = job["locations"]
        employer = (job.get("employer") or "").strip()
        if employer:
            entry["employer"] = employer
        description = (job.get("description_text") or "").strip()
        if description:
            entry["description_text"] = description
        out.append(entry)
    return out

from __future__ import annotations

from collections import defaultdict

from relocation_jobs.catalog.repo import sync_aggregator_employer_jobs
from relocation_jobs.fetch.log import log_event
from relocation_jobs.roles.match import job_is_default_match
from relocation_jobs.roles.service import annotate_listings, default_keyword_lists
from relocation_jobs.scrape.filter import filter_relevant_jobs
from relocation_jobs.shared.board_contract import (
    AGGREGATOR_ATS_TYPES,
    SOURCED_ATS_TYPE,
)

_SOURCE_LABEL = {
    "remoteok": "remoteok",
    "remotedxb": "remotedxb",
    "joblet": "joblet",
    "kake": "kake",
}


def is_aggregator_ats(ats_type: str | None) -> bool:
    return (ats_type or "").strip().lower() in AGGREGATOR_ATS_TYPES


def should_skip_country_fetch(ats_type: str | None) -> bool:
    return (ats_type or "").strip().lower() == SOURCED_ATS_TYPE


def group_jobs_by_employer(jobs: list[dict]) -> dict[str, list[dict]]:
    grouped: dict[str, list[dict]] = defaultdict(list)
    for job in jobs:
        employer = (job.get("employer") or "").strip()
        if not employer:
            continue
        entry = {
            "title": (job.get("title") or "").strip(),
            "url": (job.get("url") or "").strip(),
        }
        location = (job.get("location") or "").strip()
        if location:
            entry["location"] = location
        if job.get("locations") is not None:
            entry["locations"] = job["locations"]
        entry["matches_default_filter"] = 1 if job_is_default_match(job) else 0
        description = (job.get("description_text") or "").strip()
        if description:
            entry["description_text"] = description
        if entry["title"] and entry["url"]:
            grouped[employer].append(entry)
    return dict(grouped)


def sync_aggregator_board(
    country_key: str,
    source_company: dict,
    raw_jobs: list[dict],
    *,
    relevant_only: bool = True,
) -> tuple[int, int, list[dict]]:
    ats = (source_company.get("ats_type") or "").strip().lower()
    source = _SOURCE_LABEL.get(ats, ats or "aggregator")
    includes, excludes = default_keyword_lists()
    listed = annotate_listings(filter_relevant_jobs(raw_jobs, False), includes, excludes)
    grouped = group_jobs_by_employer(listed)
    employers = 0
    job_total = 0
    matched: list[dict] = []
    careers_fallback = (
        (source_company.get("careers_url") or source_company.get("ats_url") or "").strip()
    )
    for employer, jobs in grouped.items():
        if not jobs:
            continue
        sync_aggregator_employer_jobs(
            country_key,
            employer,
            jobs,
            source=source,
            careers_url=careers_fallback or jobs[0]["url"],
        )
        counted = jobs if not relevant_only else [
            job for job in jobs if job_is_default_match(job)
        ]
        if not counted:
            continue
        employers += 1
        job_total += len(counted)
        matched.extend(counted)
    log_event(
        f"aggregator sync employers={employers} jobs={job_total}",
        company=source_company.get("name") or "",
    )
    return employers, job_total, matched


def aggregator_success_line(prefix: str, employers: int, jobs: int) -> str:
    return f"{prefix} — aggregator: {jobs} job(s) across {employers} employer(s)"

