.role-prefs-body {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.role-prefs-list {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
  max-height: 45vh;
  overflow: auto;
}

.role-prefs-group {
  margin: 0.2rem 0 0;
  font-size: 0.75rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--muted);
}

.role-prefs-empty {
  margin: 0;
  font-size: 0.85rem;
  color: var(--muted);
}

.role-prefs-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.role-prefs-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  max-width: 100%;
  padding: 0.28rem 0.65rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--surface2);
  color: var(--text);
  font: inherit;
  font-size: 0.82rem;
  line-height: 1.2;
  cursor: pointer;
}

