async function loadRolePrefs() {
  const status = $("jobPrefsStatus");
  if (status) {
    status.hidden = false;
    status.textContent = "Loading tags…";
  }
  let res;
  try {
    res = await apiFetch("/api/role-preferences");
  } catch {
    showLogin();
    return;
  }
  if (!res.ok) {
    if (status) status.textContent = "Could not load tags.";
    return;
  }
  showApp();
  const data = await res.json();
  tags = data.tags || [];
  mine = data.mine || [];
  renderTags();
}

